scripts.generate-version:
node -e "const v=require('./package.json').version;const{execSync}=require('child_process');let h='unknown';try{h=execSync('git rev-parse --short HEAD',{stdio:['pipe','pipe','pipe']}).toString().trim()}catch{};const t=new Date().toISOString().slice(0,19).replace('T',' ');require('fs').writeFileSync('src/version.ts','// Auto-generated — do not edit manually.
// Regenerated by build/dev from package.json version.
export const APP_VERSION = "'+v+'";
export const GIT_COMMIT = "'+h+'";
export const BUILD_TIME = "'+t+'";
')"
